/* ═══════════════════════════════════════════
   DESKTOP  (≥1025px)
═══════════════════════════════════════════ */
@media(min-width:1025px){

  /* Top red announcement bar */
  #masthead{
    writing-mode:horizontal-tb!important;
    transform:none!important;
    width:100%!important;
  }
  #masthead::before{
    content:"Nepal's most trusted study abroad consultancy — Est. 2015 \A0\A0\A0|\A0\A0\A0 (+977) 9851315991"!important;
    display:block!important;
    width:100%!important;
    background:#C0392B!important;
    color:#fff!important;
    font-size:11px!important;
    padding:7px 24px!important;
    text-align:center!important;
    letter-spacing:.02em!important;
    writing-mode:horizontal-tb!important;
    white-space:nowrap!important;
    box-sizing:border-box!important;
    transform:none!important;
  }

  /* Main header bar */
  .elementor-element-307a6b3{
    background:#fff!important;
    border-bottom:1px solid #f0f0f0!important;
    box-shadow:0 2px 12px rgba(0,0,0,.06)!important;
    padding:0!important;
    position:sticky!important;
    top:0!important;
    z-index:9999!important;
  }
  .elementor-element-307a6b3 .elementor-container{
    max-width:1200px!important;
    margin:0 auto!important;
    padding:0 24px!important;
    flex-wrap:nowrap!important;
    align-items:center!important;
    min-height:64px!important;
  }

  /* Logo */
  .elementor-element-a35eeb8 img{
    max-height:48px!important;
    width:auto!important;
  }

  /* Hide redundant "Transit Education" nav link */
  li#menu-item-918,
  .menu-item-918,
  a[href="https://transiteducation.com.np/"].hfe-menu-item{
    display:none!important;
  }

  /* Hide search widget */
  .elementor-element-9dc8186{display:none!important;}

  /* Nav links */
  .hfe-nav-menu__layout-horizontal,
  .hfe-nav-menu__layout-horizontal .hfe-nav-menu{
    flex-wrap:nowrap!important;
    white-space:nowrap!important;
  }
  .hfe-nav-menu__layout-horizontal .hfe-menu-item{
    font-size:12px!important;
    font-weight:500!important;
    color:#333!important;
    padding:8px 10px!important;
    white-space:nowrap!important;
    transition:color .15s!important;
    border-bottom:2px solid transparent!important;
  }
  .hfe-nav-menu__layout-horizontal .hfe-menu-item:hover,
  .hfe-nav-menu__layout-horizontal .current-menu-item .hfe-menu-item{
    color:#C0392B!important;
    border-bottom-color:#C0392B!important;
  }

  /* Dropdown menus */
  .hfe-nav-menu .sub-menu{
    background:#fff!important;
    border-top:2px solid #C0392B!important;
    border-radius:0 0 8px 8px!important;
    box-shadow:0 8px 24px rgba(0,0,0,.1)!important;
    min-width:200px!important;
    padding:4px 0!important;
  }
  .hfe-nav-menu .sub-menu .hfe-sub-menu-item{
    font-size:13px!important;
    color:#333!important;
    padding:10px 18px!important;
    border-bottom:1px solid #f5f5f5!important;
    transition:all .15s!important;
    display:block!important;
  }
  .hfe-nav-menu .sub-menu .hfe-sub-menu-item:hover{
    color:#C0392B!important;
    background:#fef9f9!important;
    padding-left:24px!important;
  }

  /* Free Consultation button */
  #te-free-consult a{
    background:#C0392B!important;
    color:#fff!important;
    padding:10px 20px!important;
    border-radius:6px!important;
    font-size:13px!important;
    font-weight:600!important;
    text-decoration:none!important;
    white-space:nowrap!important;
    transition:background .2s!important;
    font-family:inherit!important;
    margin-left:12px!important;
    display:inline-block!important;
  }
  #te-free-consult a:hover{background:#A93226!important;}
}


/* ═══════════════════════════════════════════
   MOBILE  (≤1024px)
═══════════════════════════════════════════ */
@media(max-width:1024px){

  /* Hide original theme header */
  #masthead,
  .site-header,
  .main-header-bar,
  .ast-mobile-header-wrap,
  #ast-mobile-header{
    display:none!important;
  }

  /* Our custom mobile nav bar */
  #te-mobile-nav{
    display:flex!important;
    position:fixed!important;
    top:0!important;
    left:0!important;
    right:0!important;
    height:56px!important;
    background:#fff!important;
    z-index:100001!important;
    box-shadow:0 2px 10px rgba(0,0,0,.08)!important;
    align-items:center!important;
    justify-content:space-between!important;
    padding:0 14px!important;
    box-sizing:border-box!important;
  }

  body{ padding-top:56px!important; }
  html,body{ overflow-x:hidden!important; max-width:100vw!important; }
}


/* ═══════════════════════════════════════════
   PANEL  (all breakpoints)
═══════════════════════════════════════════ */
#te-panel{
  position:fixed!important;
  top:0!important; left:0!important; right:0!important; bottom:0!important;
  width:100vw!important;
  max-width:100vw!important;
  z-index:999999!important;
  transform:translateX(100%)!important;
}
#te-panel.open{ transform:translateX(0)!important; }

/* Close button */
#te-close, button#te-close{
  background:rgba(255,255,255,.2)!important;
  border:1.5px solid rgba(255,255,255,.35)!important;
  color:#fff!important;
  border-radius:8px!important;
  width:34px!important;
  height:34px!important;
  padding:0!important;
  box-shadow:none!important;
  text-transform:none!important;
  letter-spacing:0!important;
  font-size:18px!important;
  line-height:1!important;
}


/* ═══════════════════════════════════════════
   MOBILE CONTENT FIXES  (≤767px)
═══════════════════════════════════════════ */
@media(max-width:767px){

  .elementor-section,
  .elementor-container,
  .elementor-column,
  .elementor-widget-wrap{
    max-width:100%!important;
    box-sizing:border-box!important;
  }

  /* Destination cards — 1 col */
  .elementor-element-baa99b3 .elementor-column,
  .elementor-element-99e34df .elementor-column{ width:100%!important; }

  /* Destination card images */
  .elementor-element-d4f884d img,
  .elementor-element-07e6db9 img,
  .elementor-element-890c626 img,
  .elementor-element-f9b0579 img,
  .elementor-element-f98631c img,
  .elementor-element-7c9f712 img{
    height:200px!important;
    object-fit:cover!important;
    width:100%!important;
  }

  /* Services — 1 col */
  .elementor-element-147a78b0 .elementor-column,
  .elementor-element-1c06b13 .elementor-column{ width:100%!important; }

  /* Team — 2 col */
  .elementor-element-f18eb3f .elementor-column,
  .elementor-element-ef05143 .elementor-column{ width:50%!important; }

  /* Testimonials — 1 col */
  .elementor-element-236f824 .elementor-column,
  .elementor-element-fa53016 .elementor-column{
    width:100%!important;
    margin-bottom:16px!important;
  }

  /* Contact + Blog — 1 col */
  .elementor-element-r6fdv0k .elementor-column,
  .elementor-element-8de9fa0 .elementor-column{
    width:100%!important;
    margin-bottom:20px!important;
  }

  /* Footer */
  .elementor-223 .elementor-column{
    width:100%!important;
    padding:0 16px 24px!important;
  }
  .elementor-element-9915f82 iframe{
    width:100%!important;
    max-width:100%!important;
  }

  /* Heading size */
  .elementor-element-f2ce5e6 .elementor-heading-title{
    font-size:32px!important;
  }
}
